// src/features/auth/components/OAuthSuccess.jsx
// Handles the redirect after successful OAuth authentication.

import { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../contexts/AuthContext";
import { fetchUserProfile } from "../services/authService"; // Use feature-specific service

const OAuthSuccess = () => {
  const navigate = useNavigate();
  const { login } = useAuth();

  useEffect(() => {
    const processOAuth = async () => {
      const params = new URLSearchParams(window.location.search);
      const token = params.get("token");

      if (token) {
        localStorage.setItem("token", token);
        try {
          const user = await fetchUserProfile();
          if (user) {
            // Use the login function which properly updates the auth state
            await login({ user: user, token: token }); // Pass both user and token
            // Navigation is handled by the login effect in AuthContext
            // navigate("/dashboard", { replace: true });
          } else {
            console.error("OAuth Error: Could not fetch user profile after getting token.");
            navigate("/login");
          }
        } catch (error) {
          console.error("OAuth Error fetching profile:", error);
          navigate("/login");
        }
      } else {
        console.error("OAuth Error: No token found in URL params.");
        navigate("/login");
      }
    };

    processOAuth();
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [navigate, login]); // Dependencies: navigate, login

  return (
    <div className="flex items-center justify-center min-h-screen">
      <div className="text-center">
        <h2 className="text-xl font-semibold mb-2">Signing you in...</h2>
        <p className="text-gray-600">
          Please wait while we complete the authentication.
        </p>
         <div className="w-8 h-8 border-4 border-t-blue-500 border-b-blue-500 rounded-full animate-spin mx-auto mt-4"></div>
      </div>
    </div>
  );
};

export default OAuthSuccess;

// src/features/dashboard/components/DashboardLayout.jsx
// Provides the main layout structure for the authenticated dashboard area, including Navbar and Sidebar.

import React, { useState, useEffect } from "react";
import { Outlet, useNavigate, useLocation } from "react-router-dom";
import Sidebar from "./Sidebar";
import Navbar from "./Navbar";
import { Sheet, SheetContent } from "../../../components/ui/sheet"; // Corrected path
import TaskForm from "../../tasks/components/TaskForm"; // Corrected path
import { Button } from "../../../components/ui/button"; // Corrected path
import { useAuth } from "../../auth/contexts/AuthContext"; // Corrected path
import { Input } from "../../../components/ui/input"; // Corrected path
import { useToast } from "../../../hooks/use-toast"; // Corrected path
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "../../../components/ui/dialog"; // Corrected path
import {
  getProjects,
  createProject,
  deleteProject as apiDeleteProject, // Renamed to avoid conflict
  deleteProjectByName,
  initializeProjects,
} from "../../projects/services/projectService"; // Corrected path
import { FolderPlus, X, Check } from "lucide-react";
import { Label } from "../../../components/ui/label"; // Corrected path
import { getProjectFromPath } from "../utils/dashboardUtils"; // Helper function

const DashboardLayout = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  const { toast } = useToast();

  const [allProjects, setAllProjects] = useState([]);
  const [projectObjects, setProjectObjects] = useState([]);
  const [loadingProjects, setLoadingProjects] = useState(true);
  const [taskFormOpen, setTaskFormOpen] = useState(false);
  const [taskFormProject, setTaskFormProject] = useState(null); // For pre-filling project in form
  const [addProjectOpen, setAddProjectOpen] = useState(false);
  const [newProjectName, setNewProjectName] = useState("");
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(
    typeof window !== "undefined" ? window.innerWidth < 768 : false
  );

  // Derive selectedProject directly from URL using the utility function
  const selectedProject = React.useMemo(() => {
    const projectFromUrl = getProjectFromPath(location.pathname);
    console.log(`[DashboardLayout] Current Path: ${location.pathname}, Derived Project: ${projectFromUrl}`);
    // Update localStorage whenever the derived project changes
    localStorage.setItem("selectedProject", projectFromUrl);
    return projectFromUrl;
  }, [location.pathname]);

  // Effect to load projects
  useEffect(() => {
    let isMounted = true;
    const loadProjects = async () => {
      setLoadingProjects(true);
      try {
        let response = await getProjects();

        if (
          !response ||
          !response.success ||
          (response.success && response.data.length === 0)
        ) {
          console.log("No projects found or fetch failed, attempting initialization...");
          const initResponse = await initializeProjects();
          if (initResponse.success) {
            toast({
              title: "Projects Initialized",
              description: initResponse.data.message || "Default projects created.",
            });
            response = await getProjects(); // Re-fetch after initialization
          } else {
            throw new Error(
              initResponse.error || "Failed to initialize projects"
            );
          }
        }

        if (isMounted && response.success) {
          const fetchedProjects = response.data || [];
          setProjectObjects(fetchedProjects);
          const projectNames = fetchedProjects.map((p) => p.name);
          const projectsWithInbox = [
            "Inbox",
            ...projectNames.filter((p) => p !== "Inbox").sort(), // Sort other projects alphabetically
          ];
          setAllProjects(projectsWithInbox);
        } else if (isMounted && !response.success) {
            console.error("Failed to load projects:", response.error);
            setAllProjects(["Inbox"]); // Fallback
        }

      } catch (error) {
        console.error("Error loading or initializing projects:", error);
        if (isMounted) {
           setAllProjects(["Inbox"]); // Fallback on error
        }
      } finally {
        if (isMounted) {
          setLoadingProjects(false);
        }
      }
    };

    loadProjects();

    // Resize listener
    const handleResize = () => {
      setIsMobile(window.innerWidth < 768);
      if (window.innerWidth >= 768) {
        setSidebarOpen(false); // Close mobile sidebar on resize to desktop
      }
    };
    window.addEventListener("resize", handleResize);

    return () => {
      isMounted = false;
      window.removeEventListener("resize", handleResize);
    };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [toast]); // Removed dependency on 'navigate'

  // Navigate based on selected project
  const handleSelectProject = (projectId) => {
    console.log(`[DashboardLayout] Navigating to project: ${projectId}`);
    const specialRoutes = ["today", "upcoming", "completed", "all", "inbox"];
    if (specialRoutes.includes(projectId)) {
      navigate(`/dashboard/${projectId}`);
    } else {
      navigate(`/dashboard/project/${encodeURIComponent(projectId)}`);
    }
    if (isMobile) {
      setSidebarOpen(false); // Close sidebar on mobile after selection
    }
  };

  const toggleSidebar = () => setSidebarOpen((prev) => !prev);
  const closeSidebar = () => setSidebarOpen(false);

  const handleOpenTaskForm = (project = null) => {
    // Use the *currently selected* project if no specific one is passed
    setTaskFormProject(project || (projectObjects.find(p => p.name === selectedProject)?.name) || 'Inbox');
    setTaskFormOpen(true);
  };
  const handleCloseTaskForm = () => setTaskFormOpen(false);

  const handleSidebarAction = (action) => {
    if (action === "addProject") setAddProjectOpen(true);
    // Removed Search/Filter actions as they are now handled in TaskList
  };

  // Add Project
  const handleAddProject = async () => {
    const trimmedName = newProjectName.trim();
    if (!trimmedName || trimmedName === "Inbox") return;

    if (allProjects.includes(trimmedName)) {
      toast({
        title: "Project Already Exists",
        description: `A project named "${trimmedName}" already exists.`,
        variant: "destructive",
      });
      return;
    }

    try {
      const response = await createProject({ name: trimmedName });
      if (response.success) {
        const newProject = response.data;
        setProjectObjects((prev) => [...prev, newProject]);
        setAllProjects((prev) => [...prev, newProject.name].sort((a,b) => a === 'Inbox' ? -1 : b === 'Inbox' ? 1 : a.localeCompare(b))); // Keep Inbox first, sort others
        toast({ title: "Project Created" });
        setNewProjectName("");
        setAddProjectOpen(false);
      } else {
        throw new Error(response.error || "Failed to create project");
      }
    } catch (error) {
      console.error("Error creating project:", error);
      toast({ title: "Error Creating Project", description: error.message, variant: "destructive" });
    }
  };

  // Delete Project
  const handleDeleteProject = async (projectName) => {
    if (projectName === "Inbox") {
      toast({ title: "Cannot Delete Inbox", variant: "destructive" });
      return;
    }

    const project = projectObjects.find((p) => p.name === projectName);
    if (!project?._id) {
        toast({ title: "Project not found", description: `Could not find project ID for ${projectName}`, variant: "destructive" });
        // Attempt deletion by name as a fallback? Risky.
        // console.warn(`Attempting to delete project ${projectName} by name as ID was not found.`);
        // const fallbackResponse = await deleteProjectByName(projectName);
        return; 
    }

    try {
      const response = await apiDeleteProject(project._id);
      if (response.success) {
        setProjectObjects((prev) => prev.filter((p) => p._id !== project._id));
        setAllProjects((prev) => prev.filter((p) => p !== projectName));
        toast({ title: "Project Deleted", description: response.data.message });
        if (selectedProject === projectName) {
          handleSelectProject("today"); // Navigate away if deleted project was selected
        }
      } else {
        throw new Error(response.error || "Failed to delete project");
      }
    } catch (error) {
      console.error("Error deleting project:", error);
      toast({ title: "Error Deleting Project", description: error.message, variant: "destructive" });
    }
  };

  return (
    <div className="h-screen flex flex-col overflow-hidden bg-gradient-to-br from-gray-50 to-blue-50 dark:from-zinc-950 dark:to-indigo-950">

      {/* Mobile Only: Sidebar as Sheet - Pass isOpen and onClose */} 
      {isMobile && (
        <Sidebar
          selectedProject={selectedProject}
          onSelectProject={handleSelectProject}
          myProjects={allProjects}
          onAddTask={handleOpenTaskForm}
          onSidebarAction={handleSidebarAction}
          onDeleteProject={handleDeleteProject}
          username={user?.name || "User"}
          isOpen={sidebarOpen}
          onClose={closeSidebar}
          isMobile={isMobile} // Pass isMobile prop
          loadingProjects={loadingProjects}
        />
      )}

      {/* Navbar - Always visible, pass toggle function */}
      <Navbar
        onSidebarToggle={toggleSidebar}
        onAddTask={handleOpenTaskForm}
        selectedProject={selectedProject} // Pass selectedProject for context if needed
        className="bg-white/40 dark:bg-zinc-900/40 backdrop-blur-xl border-b border-gray-200/40 dark:border-zinc-700/40 shadow-sm"
      />

      {/* Main Content Area */} 
      <div className="flex flex-1 overflow-hidden">
        {/* Desktop Only: Permanent Sidebar */} 
        {!isMobile && (
          <Sidebar
            selectedProject={selectedProject}
            onSelectProject={handleSelectProject}
            myProjects={allProjects}
            onAddTask={handleOpenTaskForm}
            onSidebarAction={handleSidebarAction}
            onDeleteProject={handleDeleteProject}
            username={user?.name || "User"}
            loadingProjects={loadingProjects}
            className="w-64 flex-shrink-0" // Fixed width for desktop sidebar
          />
        )}

        {/* Content Outlet */} 
        <main className="flex-1 overflow-auto bg-white/20 dark:bg-zinc-900/20 backdrop-blur-sm scrollbar-thin scrollbar-thumb-transparent scrollbar-track-transparent hover:scrollbar-thumb-gray-300/20 dark:hover:scrollbar-thumb-gray-600/20">
          {/* Pass projects data down via context */}
          <Outlet context={{ allProjects, projectObjects, selectedProject }} />
        </main>
      </div>

      {/* TaskForm Dialog */} 
      <Dialog open={taskFormOpen} onOpenChange={setTaskFormOpen}>
        <DialogContent className="sm:max-w-[550px] max-h-[90vh] overflow-y-auto p-0 bg-gradient-to-br from-slate-50 via-purple-50 to-blue-50 dark:from-slate-950 dark:via-gray-900 dark:to-slate-900 border-0 rounded-lg shadow-lg">
          <TaskForm
            availableProjects={allProjects}
            onTaskCreated={handleCloseTaskForm}
            initialProject={taskFormProject} // Pass the project to pre-fill
          />
        </DialogContent>
      </Dialog>

      {/* Add Project Dialog */} 
      <Dialog open={addProjectOpen} onOpenChange={setAddProjectOpen}>
        <DialogContent className="sm:max-w-[400px] bg-gradient-to-br from-slate-50 via-purple-50 to-blue-50 dark:from-slate-950 dark:via-gray-900 dark:to-slate-900 border-0 rounded-lg shadow-lg">
          <DialogHeader className="pb-4">
            <DialogTitle className="text-2xl font-bold bg-gradient-to-r from-blue-600 to-purple-600 bg-clip-text text-transparent flex items-center">
              <FolderPlus className="mr-2 h-5 w-5 text-blue-600" />
              Add Project
            </DialogTitle>
          </DialogHeader>

          <div className="p-4 pt-0 space-y-4">
            <div className="space-y-2">
              <Label htmlFor="project-name" className="font-medium">
                Project Name
              </Label>
              <Input
                id="project-name"
                type="text"
                value={newProjectName}
                onChange={(e) => setNewProjectName(e.target.value)}
                placeholder="Enter project name"
                className="bg-white/50 dark:bg-gray-800/50"
              />
            </div>

            <DialogFooter className="pt-2">
              <Button 
                onClick={handleAddProject} 
                disabled={!newProjectName.trim() || loadingProjects}
                className="w-full bg-gradient-to-r from-indigo-500 to-purple-600 hover:from-indigo-600 hover:to-purple-700 text-white"
              >
                <span className="flex items-center justify-center">
                  <FolderPlus className="mr-2 h-4 w-4" />
                  Add Project
                </span>
              </Button>
            </DialogFooter>
          </div>
        </DialogContent>
      </Dialog>

      {/* Removed Search/Filter Sheets - Functionality moved to TaskList */} 

      {/* Overlay for mobile when sidebar is open */} 
      {isMobile && sidebarOpen && (
        <div
          className="fixed inset-0 bg-black/30 z-40 backdrop-blur-sm"
          onClick={closeSidebar}
        />
      )}
    </div>
  );
};

export default DashboardLayout;

// src/features/dashboard/components/Navbar.jsx
// Renders the top navigation bar, handling theme toggle, user menu, and sidebar toggle for mobile.

import React, { useEffect, useState } from "react";
import { Link, useNavigate, useLocation } from "react-router-dom";
import { useAuth } from "../../auth/contexts/AuthContext"; // Corrected path
import { Menu, Sun, Moon, LogOut, User, Settings } from "lucide-react";
import { Button } from "../../../components/ui/button"; // Corrected path
import { Avatar, AvatarFallback, AvatarImage } from "../../../components/ui/avatar"; // Corrected path
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
  DropdownMenuSeparator
} from "../../../components/ui/dropdown-menu"; // Corrected path
import { motion } from "framer-motion";

const Navbar = ({ onSidebarToggle, onAddTask, className }) => {
  const { isAuthenticated, user, logout } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();

  // Check if we're on login or signup page (public view)
  const isPublicAuthPage = ['/login', '/signup'].includes(location.pathname);

  const [dark, setDark] = useState(() => {
    const savedTheme = localStorage.getItem("theme");
    if (savedTheme) return savedTheme === "dark";
    return window.matchMedia?.("(prefers-color-scheme: dark)").matches ?? false;
  });

  useEffect(() => {
    document.documentElement.classList.toggle("dark", dark);
    localStorage.setItem("theme", dark ? "dark" : "light");
  }, [dark]);

  const toggleDark = () => setDark((d) => !d);

  const handleLogout = () => {
    logout();
    navigate("/login", { replace: true }); // Navigate after logout
  };

  const getUserInitials = () => {
    if (!user?.name) return "U";
    return user.name.split(" ").map((n) => n[0]).join("").toUpperCase().substring(0, 2);
  };

  // Adjust styles based on authentication state for clearer separation
  const navbarClasses = className || (
    isAuthenticated
    ? "bg-white/50 dark:bg-zinc-900/50 backdrop-blur-xl border-b border-gray-200/40 dark:border-zinc-700/40 sticky top-0 z-30 shadow-sm" // Dashboard Navbar Style
    : "bg-white/20 dark:bg-gray-800/90 backdrop-blur-md border-b border-white/10 dark:border-gray-700 sticky top-0 z-30 shadow-sm" // Public Navbar Style
  );

  const buttonClass = isAuthenticated
    ? "bg-white/30 dark:bg-zinc-800/30 backdrop-blur-sm hover:bg-white/50 dark:hover:bg-zinc-800/50"
    : (dark ? "bg-gray-700 hover:bg-gray-600 text-white" : "bg-white/40 hover:bg-white/60 text-gray-800");

  return (
    <motion.nav
      className={navbarClasses}
      initial={{ y: -20, opacity: 0 }}
      animate={{ y: 0, opacity: 1 }}
      transition={{ type: "spring", stiffness: 400, damping: 20 }}
    >
      <div className="px-4 py-2 flex items-center justify-between h-14">
        <div className="flex items-center gap-2">
          {isAuthenticated && (
            <div className="flex items-center md:hidden"> {/* Only show on mobile */} 
              <motion.div whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.9 }}>
                <Button
                  variant="ghost"
                  size="icon"
                  onClick={onSidebarToggle} // Use the passed toggle function
                  aria-label="Toggle sidebar"
                >
                  <Menu className="h-5 w-5" />
                </Button>
              </motion.div>
            </div>
          )}
          <Link
            to={isAuthenticated ? "/dashboard" : "/"}
            className="text-xl font-bold text-primary dark:text-primary/90"
          >
            Task Tree
          </Link>
        </div>

        <div className="flex items-center space-x-2">
          <motion.div
            whileHover={{ scale: 1.15, rotate: dark ? 25 : -25 }}
            whileTap={{ scale: 0.85 }}
            transition={{ type: "spring", stiffness: 400, damping: 10 }}
          >
            <Button
              variant="ghost"
              className={`${buttonClass} rounded-full`}
              size="icon"
              aria-label="Toggle dark mode"
              onClick={toggleDark}
            >
              {dark ? (
                <Sun className="h-5 w-5 text-yellow-400" />
              ) : (
                <Moon className="h-5 w-5 text-gray-600" />
              )}
            </Button>
          </motion.div>

          {isAuthenticated ? (
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <Button
                  variant="ghost"
                  className={`${buttonClass} rounded-full h-9 w-9 p-0`}
                  aria-label="User menu"
                >
                  <Avatar className="h-8 w-8">
                    <AvatarImage
                      src={user.photo || `https://avatar.vercel.sh/${user.email || user.name}.png`}
                      alt={user.name || 'User'}
                      className="border-2 border-transparent group-hover:border-primary/30"
                    />
                    <AvatarFallback className="bg-gradient-to-br from-primary to-primary/70 text-white font-medium">
                      {getUserInitials()}
                    </AvatarFallback>
                  </Avatar>
                </Button>
              </DropdownMenuTrigger>
              <DropdownMenuContent
                align="end"
                className="bg-white/80 dark:bg-zinc-900/80 backdrop-blur-xl border-gray-200/40 dark:border-zinc-700/40 shadow-lg rounded-lg mt-1 w-48"
              >
                 <DropdownMenuItem asChild>
                   <Link to="/dashboard/settings" className="cursor-pointer flex items-center text-sm py-1.5 px-2">
                     <Settings className="mr-2 h-4 w-4 text-muted-foreground" />
                     <span>Settings</span>
                   </Link>
                 </DropdownMenuItem>
                 <DropdownMenuSeparator />
                 <DropdownMenuItem onClick={handleLogout} className="cursor-pointer flex items-center text-sm py-1.5 px-2 text-red-600 dark:text-red-400 focus:bg-red-50 dark:focus:bg-red-900/30 focus:text-red-700 dark:focus:text-red-300">
                   <LogOut className="mr-2 h-4 w-4" />
                   <span>Log out</span>
                 </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          ) : (
            // Show Login/Signup buttons only if NOT on those pages already
            !isPublicAuthPage && (
              <div className="flex items-center gap-2">
                <Button variant="ghost" size="sm" asChild>
                  <Link to="/login">Login</Link>
                </Button>
                <Button size="sm" asChild>
                  <Link to="/signup">Sign Up</Link>
                </Button>
              </div>
            )
          )}
        </div>
      </div>
    </motion.nav>
  );
};

export default Navbar;

