// src/features/projects/components/KanbanColumn.jsx
// Renders a single column in the Kanban board.

import React from "react";
import KanbanTaskCard from "./KanbanTaskCard";
import { SortableContext, verticalListSortingStrategy } from "@dnd-kit/sortable";
import { useDroppable } from "@dnd-kit/core";
import { motion } from "framer-motion";

const KanbanColumn = ({ id, title, tasks = [] }) => {
  // Set up droppable area for the column
  const { setNodeRef, isOver } = useDroppable({
    id: id, // Use the column id ('todo', 'doing', 'completed')
    data: {
      type: 'column',
      accepts: ['task'], // Define what type of draggable this droppable accepts
    }
  });

  const columnVariants = {
    hidden: { opacity: 0, y: 15 },
    visible: (i) => ({
      opacity: 1,
      y: 0,
      transition: { delay: i * 0.1, duration: 0.4, ease: "easeOut" }
    })
  };

  // Determine index based on ID for staggered animation
  const columnIndex = ['todo', 'doing', 'completed'].indexOf(id);

  return (
    <motion.div
      ref={setNodeRef}
      variants={columnVariants}
      initial="hidden"
      animate="visible"
      custom={columnIndex} // Pass index for staggered animation
      className={`w-full md:w-[280px] lg:w-[320px] flex-shrink-0 rounded-xl flex flex-col h-full ${isOver ? 'ring-2 ring-primary/50 bg-primary/5' : ''}`}
      style={{ minHeight: '400px' }} // Ensure columns have a minimum height
    >
      <div className="p-3 border-b border-border sticky top-0 bg-muted/40 dark:bg-zinc-800/40 backdrop-blur-sm rounded-t-xl z-10">
          <h2 className="font-semibold text-sm text-center capitalize">
              {title} ({tasks.length})
          </h2>
      </div>

      <SortableContext
        items={tasks.map((t) => t._id)} // Provide IDs of sortable items in this column
        strategy={verticalListSortingStrategy}
      >
        <div
          className={`flex-grow overflow-y-auto p-2 space-y-2 scrollbar-thin scrollbar-thumb-muted-foreground/30 scrollbar-track-transparent rounded-b-xl ${isOver ? 'bg-primary/5' : 'bg-muted/20 dark:bg-zinc-900/30'}`}
        >
          {tasks.map((task) => (
            <KanbanTaskCard
              key={task._id}
              task={task}
              // onStatusChange is handled by DndContext dragEnd in the parent board
            />
          ))}
          {tasks.length === 0 && !isOver && (
            <p className="text-xs text-muted-foreground text-center pt-4 px-2">
              Drag tasks here or add new ones.
            </p>
          )}
           {/* Visual indicator for drop target */} 
          {isOver && (
            <div className="border-2 border-dashed border-primary/50 rounded-lg p-4 mt-2">
              <p className="text-xs text-center text-primary/80">
                Drop task here
              </p>
            </div>
          )}
        </div>
      </SortableContext>
    </motion.div>
  );
};

export default KanbanColumn;

// src/features/projects/components/KanbanTaskCard.jsx
// Renders a draggable task card for the Kanban board.

import React from "react";
import { Card, CardContent } from "../../../components/ui/card"; // Corrected path
import { Badge } from "../../../components/ui/badge"; // Corrected path
import { getPriorityVariant } from "../../../lib/utils"; // Corrected path
import { useSortable } from "@dnd-kit/sortable";
import { CSS } from "@dnd-kit/utilities";
import { Calendar } from "lucide-react";
import { motion } from "framer-motion";

const KanbanTaskCard = ({ task, overlay }) => {
  const { 
    attributes, 
    listeners, 
    setNodeRef, 
    transform, 
    transition, 
    isDragging 
  } = useSortable({ 
      id: task._id, 
      data: { type: 'task', task } // Add type and potentially task data
  });

  // Style for dragging effect
  const style = {
    transform: CSS.Transform.toString(transform),
    transition: transition || 'transform 250ms ease', // Add default transition
    opacity: isDragging ? 0.7 : 1,
    zIndex: isDragging ? 100 : 'auto', // Ensure dragged item is on top
    cursor: isDragging ? 'grabbing' : 'grab',
  };

  if (!task) return null;

  // Base classes
  const cardClasses = "p-2 md:p-2.5 border rounded-lg shadow-sm transition-all duration-200 touch-none will-change-transform";
  // Specific styles for normal card
  const normalCardClasses = "bg-card/80 dark:bg-zinc-800/70 border-border/70 hover:shadow-md hover:scale-[1.03] hover:border-primary/50 hover:z-10 relative";
  // Specific styles for overlay (dragged) card
  const overlayCardClasses = "bg-card dark:bg-zinc-800 border-primary/50 shadow-xl scale-[1.05]";

  return (
    <motion.div
      ref={setNodeRef}
      style={style}
      className={`${overlay ? 'kanban-overlay-card' : 'kanban-task-card'}`}
      {...attributes}
      {...listeners}
      // layout // Enable layout animation
    >
      <Card
        className={cn(
          cardClasses,
          overlay ? overlayCardClasses : normalCardClasses
        )}
      >
        <CardContent className="p-0">
          <h3 className="font-medium text-xs md:text-sm mb-1.5 line-clamp-2 break-words">
            {task.title}
          </h3>
          <div className="flex flex-wrap gap-1 items-center text-[10px] md:text-[11px]">
            {task.priority && (
              <Badge
                variant={getPriorityVariant(task.priority)}
                className="px-1.5 py-0 h-4 leading-tight"
              >
                {task.priority}
              </Badge>
            )}
            {task.dueDate && (
              <span className="text-muted-foreground flex items-center">
                 <Calendar className="h-3 w-3 mr-0.5" />
                {new Date(task.dueDate).toLocaleDateString('en-US', { month: 'short', day: 'numeric' })}
              </span>
            )}
             {task.labels && task.labels.length > 0 && (
                 <Badge variant="outline" className="px-1.5 py-0 h-4 leading-tight">
                   {task.labels[0]}
                   {task.labels.length > 1 ? ` +${task.labels.length - 1}` : ''}
                 </Badge>
             )}
          </div>
        </CardContent>
      </Card>
    </motion.div>
  );
};

// Helper cn function (if not globally available)
function cn(...inputs) {
  return inputs.filter(Boolean).join(' ');
}

export default KanbanTaskCard;

